import random


def gen_input(n: int, seed: int) -> str:
    rng = random.Random(seed)
    ops = max(1, min(int(n), 100))
    memory = rng.randint(1, 100)
    lines = [f"{ops} {memory}"]
    for _ in range(ops):
        kind = rng.randrange(3)
        if kind == 0:
            lines.append(f"alloc {rng.randint(1, 100)}")
        elif kind == 1:
            lines.append(f"erase {rng.randint(-20, 150)}")
        else:
            lines.append("defragment")
    return "\n".join(lines) + "\n"

import random


def gen_input(n: int, seed: int) -> str:
    rng = random.Random(seed)
    size = max(1, min(int(n), 100))
    lines = [str(size)]
    for _ in range(size):
        flags = [rng.randint(0, 1) for _ in range(10)]
        if not any(flags):
            flags[rng.randrange(10)] = 1
        lines.append(" ".join(map(str, flags)))
    for _ in range(size):
        lines.append(" ".join(str(rng.randint(-10000000, 10000000)) for _ in range(11)))
    return "\n".join(lines) + "\n"
